window.EL_GAME_THEORY={"2eso-ls2-lp1-grammar":{"title":"Grammar · Present Simple: how often?","parts":[{"k":"p1","name":"Present Simple: he / she / it + -s","nameCa":"Present Simple: la -s de he / she / it","n":5,"slides":[{"theory":"The Present Simple: habits","img":"🔁","lines":["We use the **Present Simple** for things we do **often**, **usually** or **every week**.",{"table":[["I / you / we / they","he / she / it"],["I **play** football.","Hugo **plays** football."],["We **go** skating.","Marta **goes** skating."],["They **don't draw**.","She **doesn't draw**."]]},{"watch":"After **doesn't**, no -s: She doesn't ~~plays~~ **play**."}],"ca":["Present Simple = hàbits, coses que fem sovint.","Amb he / she / it el verb porta -s. A la negativa: don't / doesn't + verb sense -s."]},{"theory":"he / she / it: -s, -es or -ies?","img":"✏️","lines":[{"table":[["The verb ends in…","he / she / it","Examples"],["most verbs","+ **-s**","play → play**s** · draw → draw**s**"],["-o, -ch, -sh, -ss, -x","+ **-es**","go → go**es** · do → do**es** · watch → watch**es**"],["consonant + y","y → **-ies**","study → stud**ies** · fly → fl**ies**"],["have","irregular","have → **has**"]]},{"watch":"Vowel + y: only -s: play → play**s** (not ~~plaies~~)."}],"ca":["La majoria de verbs: -s. Acabats en -o, -ch, -sh, -ss, -x: -es.","Consonant + y: canvia la y per -ies. Have → has."]}]},{"k":"p2","name":"Present Simple: questions and short answers","nameCa":"Present Simple: preguntes i respostes curtes","n":5,"slides":[{"theory":"Questions and short answers","img":"❓","lines":[{"table":[["Question","Short answer"],["**Do** you **play** the guitar?","Yes, I **do**. / No, I **don't**."],["**Does** she **go** swimming?","Yes, she **does**. / No, she **doesn't**."],["**Where do** they **train**?","At the sports centre."]]},"Question word + **do / does** + subject + verb: **When does** Marta **practise**?",{"watch":"The -s goes to **does**: Does she ~~goes~~ **go**?"}],"ca":["Preguntes: Do / Does + subjecte + verb sense -s.","Resposta curta: Yes, I do. / No, she doesn't."]}]},{"k":"p3","name":"Adverbs of frequency (always, usually…)","nameCa":"Adverbis de freqüència (always, usually…)","n":6,"slides":[{"theory":"How often? Adverbs of frequency","img":"📅","lines":["**always** 100 % · **usually** · **often** · **sometimes** · **never** 0 %",{"table":[["Where does it go?","Example"],["**before** most verbs","She **usually goes** skating."],["**after** be (am / is / are)","She **is always** late."]]},"Expressions of time go at the **end**: I go swimming **once a week**. We train **twice a week**.",{"watch":"She ~~goes usually~~ → She **usually goes**."}],"ca":["L'adverbi va davant del verb, però darrere de be (am / is / are).","Once a week, twice a week, every day… van al final de la frase."]}]}]},"2eso-ls2-lp1-vocab":{"title":"Vocabulary · Free-time activities","parts":[{"k":"p1","name":"play, go or do + a sport","nameCa":"play, go o do + un esport","n":6,"slides":[{"theory":"play, go or do?","img":"⚽","lines":["**play** + a sport with a ball or a game: **play** football · **play** basketball · **play** video games","**play the** + an instrument: **play the** guitar · **play the** piano","**go** + -ing: **go** swimming · **go** skating · **go** cycling","**do** + karate, gymnastics, yoga: **do** karate · **do** yoga"]}]},{"k":"p2","name":"How often? (once a week…)","nameCa":"Cada quan? (once a week…)","n":5,"slides":[{"theory":"How often?","img":"📅","lines":["**once a week** (1) · **twice a week** (2) · **every day**","**at the weekend** · **in my free time**","**How often** do you go swimming? — **Once a week.**"]}]},{"k":"p3","name":"Hobby words (be good at, join a club…)","nameCa":"Paraules de hobbies (be good at, join a club…)","n":9,"slides":[{"theory":"Talking about hobbies","img":"🧗","lines":["**be good at**: Pol **is good at** skating. · **spend time** + -ing: I **spend** hours drawing.","**join a club** = become a member · **practise** = do it again and again to get better","Online: a **livestream** (live video) · **subscribers** (follow a channel) · **highlights** (the best moments) · **fans**"]}]}]},"2eso-ls2-lp2-grammar":{"title":"Grammar · Present Continuous","parts":[{"k":"p1","name":"Present Continuous: am / is / are + -ing","nameCa":"Present Continuous: am / is / are + -ing","n":4,"slides":[{"theory":"What's happening now?","img":"🎥","lines":["We use the **Present Continuous** for actions happening **now**.",{"table":[["","am / is / are","verb + -ing"],["I","**am** ('m)","watching the match."],["He / She / It","**is** ('s)","climbing the red route."],["We / You / They","**are** ('re)","cheering."]]},"Time words: **now** · **right now** · **at the moment** · **today** · **Look!** · **Listen!**",{"watch":"Don't forget am / is / are: ~~Nil climbing~~ → Nil **is climbing**."}],"ca":["Present Continuous = accions que passen ara mateix.","am / is / are + verb acabat en -ing. No t'oblidis mai de am / is / are."]}]},{"k":"p2","name":"Spelling the -ing form","nameCa":"Com s'escriu la forma -ing","n":4,"slides":[{"theory":"How to write the -ing form","img":"✏️","lines":[{"table":[["The verb…","Rule","Examples"],["most verbs","+ **-ing**","play → play**ing** · cheer → cheer**ing** · study → study**ing**"],["ends in -e","drop the **-e**","dance → danc**ing** · write → writ**ing** · take → tak**ing**"],["one vowel + one consonant","**double** it","run → ru**nn**ing · swim → swi**mm**ing · win → wi**nn**ing · get → ge**tt**ing"]]},{"watch":"Two vowels: no double: read → **reading** (not ~~readding~~)."}],"ca":["La majoria: + -ing. Si acaba en -e, treu la -e.","Una vocal + una consonant al final: dobla la consonant (run → running)."]}]},{"k":"p3","name":"Present Continuous: negatives and questions","nameCa":"Present Continuous: negatives i preguntes","n":8,"slides":[{"theory":"Negatives: not now","img":"🚫","lines":[{"table":[["Positive","Negative"],["I**'m** playing.","I**'m not** playing."],["She**'s** playing.","She **isn't** playing."],["They**'re** playing.","They **aren't** playing."]]},"It's raining, so we **aren't playing** outside. The Green Team **isn't winning**.",{"watch":"~~I amn't~~ → I**'m not**."}],"ca":["Negativa: posa not darrere de am / is / are: I'm not · isn't · aren't."]},{"theory":"Questions and short answers","img":"❓","lines":[{"table":[["Question","Short answer"],["**Are** you **watching**?","Yes, I **am**. / No, I**'m not**."],["**Is** Júlia **shooting**?","Yes, she **is**. / No, she **isn't**."],["**What are** they **doing**?","They're warming up."]]},"(Question word) + **am / is / are** + subject + verb-ing: **Why are** the fans **cheering**?",{"watch":"Short answers have no contraction: Yes, she **is** (not ~~Yes, she's~~)."}],"ca":["Pregunta: am / is / are davant del subjecte. Resposta curta: Yes, she is. / No, she isn't.","A la resposta curta afirmativa no hi ha contracció."]}]}]},"2eso-ls2-lp2-vocab":{"title":"Vocabulary · Clothes, kit and weather","parts":[{"k":"p1","name":"Clothes and kit","nameCa":"Roba i equipament","n":6,"slides":[{"theory":"Clothes and kit","img":"🧢","lines":["**T-shirt** · **shorts** · **trainers** (sports shoes) · **tracksuit** (sports jacket and trousers)","**cap** (for the sun) · **helmet** (protects your head on a bike)","**wear a uniform** (the same clothes for the whole team) · **wear a costume** (to look like someone else)"]}]},{"k":"p2","name":"The weather","nameCa":"El temps","n":5,"slides":[{"theory":"What's the weather like?","img":"🌦️","lines":["It's **sunny** · **cloudy** · **windy** · It's **raining** · It's **snowing**","It's **foggy** (you can't see far) · **stormy** (thunder and lightning) · **freezing** (very, very cold)","It's 25 **degrees**. · **What's the weather like?** — It's sunny."]}]},{"k":"p3","name":"At the event (match, crowd, score…)","nameCa":"Esdeveniments (match, crowd, score…)","n":7,"slides":[{"theory":"At the event","img":"🏟️","lines":["a **match** · a **tournament** (many teams) · a **competition** · a **concert** · a **fair**","**win** / **lose** a match · **score** a goal · **warm up** (get ready with some exercise) · **take part in** (participate)","the **crowd** (all the people watching) **cheers** · **half-time** (the break in the middle) · the **highlights**"]}]}]},"2eso-ls2-lp3-grammar":{"title":"Grammar · Present Simple or Present Continuous?","parts":[{"k":"p1","name":"Present Simple or Present Continuous?","nameCa":"Present Simple o Present Continuous?","n":5,"slides":[{"theory":"Usually or now?","img":"🔄","lines":[{"table":[["","Present Simple","Present Continuous"],["Use","habits, things that are always true","actions happening **now**"],["Form","I **play** · she **plays**","I**'m playing** · she**'s playing**"],["Time words","**usually**, always, never, every weekend, on Sundays, in winter","**now**, right now, at the moment, today, this weekend, Look!, Listen!"]]},"Mei **usually comes** to the ice rink on Sunday afternoons. **Right now** she**'s practising** her turns.",{"watch":"Habit + now in one sentence: I **usually go** swimming, **but today** I**'m watching** a match."}],"ca":["Present Simple = el que fas normalment (hàbits). Present Continuous = el que està passant ara.","Mira les paraules de temps: usually, every… → Present Simple; now, today, Look! → Present Continuous."]}]},{"k":"p2","name":"Questions and negatives: do / does or am / is / are","nameCa":"Preguntes i negatives: do / does o am / is / are","n":5,"slides":[{"theory":"Questions and negatives","img":"❓","lines":[{"table":[["","Present Simple (do / does)","Present Continuous (am / is / are)"],["Negative","Noah **doesn't ride** on Mondays.","Noah **isn't riding** today."],["Question","**Do** you **train** on Tuesdays?","What **are** you **doing**?"],["Short answer","Yes, I **do**. / No, she **doesn't**.","Yes, I **am**. / No, he **isn't**."]]},"**How often** do you go skating? — **Twice a week.**",{"watch":"Don't mix them: ~~Do you watching~~ → **Are** you **watching**? · ~~Is she like~~ → **Does** she **like**?"}],"ca":["Present Simple: do / does + verb (sense -s). Present Continuous: am / is / are + verb-ing.","No barregis do amb -ing."]}]},{"k":"p3","name":"State verbs (like, want, know…): never -ing","nameCa":"Verbs d'estat (like, want, know…): mai -ing","n":4,"slides":[{"theory":"State verbs: never -ing","img":"🧠","lines":["Some verbs are **states** (feelings, thoughts), not actions: **like, love, hate, want, need, know, prefer, understand, believe, mean**.","We use them in the **Present Simple**, even for now: I **want** a new helmet now. **Do** you **understand**?",{"watch":"~~I'm needing new gloves~~ → I **need** new gloves. · ~~Are you knowing~~ → **Do** you **know**?"},"**think**: opinion → I **think** skating is fun. An activity now → Be quiet! I**'m thinking** about my next video."],"ca":["Els verbs d'estat (like, want, need, know…) no van mai en -ing, encara que parlem d'ara.","think: opinió → I think…; pensar ara mateix → I'm thinking about…"]}]},{"k":"p4","name":"Present Continuous: temporary things and plans","nameCa":"Present Continuous: coses temporals i plans","n":4,"slides":[{"theory":"Not only this second: temporary","img":"📆","lines":["The Present Continuous is also for things that are true **for a short time**: **This month** I**'m training** for a race.","My cousin **is staying** with us **this week**. (Usually she lives in Lleida.)",{"watch":"Plans: **This weekend** we**'re going** to a concert. **Next week** I**'m racing** too."}],"ca":["El Present Continuous també serveix per a coses temporals (this month, this week) i per a plans (this weekend, next week)."]}]}]},"2eso-ls2-lp3-vocab":{"title":"Vocabulary · Now or usually? Time words and sport","parts":[{"k":"p1","name":"Time words: now or usually?","nameCa":"Paraules de temps: ara o normalment?","n":7,"slides":[{"theory":"Now or usually? Time words","img":"⏱️","lines":["**Now:** now · **right now** (ara mateix) · **at the moment** · today · **this weekend** · Look! · Listen!","**Usually:** usually · always · never · **every weekend** · **on Saturday mornings** · **in winter** / in summer","**How often?** once a week · **twice** a week (two times) · every day · **as usual** (like always)"]}]},{"k":"p2","name":"Sport words (practise, train, race…)","nameCa":"Paraules d'esport (practise, train, race…)","n":6,"slides":[{"theory":"Doing sport","img":"🚴","lines":["**practise** (do something again and again to get better) · **train** (prepare for a match or a race)","**watch a match** · **go to a concert** · a **race** (who is the fastest?) · **ride** a bike · **film** a video","the **ice rink** (for skating) · the **bike park** · the **temperature** is three **degrees**"]}]},{"k":"p3","name":"State verbs: what they mean","nameCa":"Verbs d'estat: què volen dir","n":5,"slides":[{"theory":"State verbs: what they mean","img":"🧠","lines":["**know** (saber, conèixer) · **need** (necessitar) · **want** (voler) · **prefer** (preferir)","**believe** (creure) · **understand** (entendre) · **mean** (voler dir): What does \"crowd\" **mean**?","Vlog words: a **livestream** (a live video) · **subscribers** (people who follow a channel) · **highlights**"]}]}]},"4eso-ls2-lp1-grammar":{"title":"Grammar · Talking about change","parts":[{"k":"p1","name":"get + comparative (it gets colder)","nameCa":"get + comparatiu (it gets colder)","n":6,"slides":[{"theory":"get + comparative = a change","img":"🌇","lines":["Read: “**In autumn the days get shorter.**” What does it mean?","Every day is a bit shorter than the day before: **get** + comparative = something **changes**.","It **gets colder**. The nights **get longer**. The streets **get more crowded** at Christmas.",{"watch":"**it gets dark early** (an adjective, not a comparative) = night comes early."}],"ca":["get + comparatiu = un canvi: els dies es fan més curts (the days get shorter).","It gets colder = cada vegada fa més fred."]},{"theory":"How to make the comparative","img":"📏","lines":[{"table":[["Adjective","Rule","get + …"],["short: cold, dark, long","+ **-er**","get cold**er** · get dark**er**"],["ends in -e: nice, wide","+ **-r**","get nice**r**"],["one vowel + one consonant: wet, hot","double + **-er**","get we**tt**er · get ho**tt**er"],["consonant + y: windy, chilly, foggy","y → **-ier**","get wind**ier** · get chill**ier**"],["long: crowded, comfortable","**more** + adjective","get **more crowded**"],["irregular: good, bad","—","get **better** · get **worse**"]]},{"watch":"~~more colder~~ → **colder**. Use **more** only with long adjectives."}],"ca":["Adjectius curts: -er (colder). Acabats en consonant + y: -ier (windier).","Adjectius llargs: more + adjectiu (more crowded). Good → better, bad → worse."]}]},{"k":"p2","name":"Present Simple or Present Continuous?","nameCa":"Present Simple o Present Continuous?","n":5,"slides":[{"theory":"Every autumn or right now?","img":"🍁","lines":[{"table":[["Present Simple: every year, in general","Present Continuous: now, these days"],["In autumn the days **get** shorter.","Look! It**'s getting** dark."],["The leaves **fall** in November.","The leaves **are falling** right now."],["It usually **rains** a lot in Manchester.","It**'s raining** at the moment."]]},"Present Simple + **usually**, **always**, **every year**, **in autumn** · Present Continuous + **now**, **at the moment**, **these days**, **Look!**",{"watch":"**It's getting colder** = it's changing now, day by day."}],"ca":["Present Simple: el que passa cada any o en general. Present Continuous: el que passa ara o aquests dies.","It's getting colder = ara mateix està canviant, cada dia fa més fred."]}]},{"k":"p3","name":"Adjective + preposition + -ing (excited about going)","nameCa":"Adjectiu + preposició + -ing (excited about going)","n":5,"slides":[{"theory":"Feelings: adjective + preposition (+ -ing)","img":"🎃","lines":[{"table":[["Adjective + preposition","+ noun","+ verb-ing"],["scared **of**","scared of **the dark**","scared of **walking** home alone"],["excited **about**","excited about **Halloween**","excited about **dressing** up"],["proud **of**","proud of **our tradition**","proud of **making** panellets"],["grateful **for**","grateful for **my family**","grateful for **having** a cosy home"]]},{"watch":"After a preposition, the verb takes **-ing**: excited about ~~go~~ **going**."}],"ca":["Després d'una preposició (of, about, for…), el verb va en -ing: excited about going."]}]}]},"4eso-ls2-lp1-vocab":{"title":"Vocabulary · Autumn words","parts":[{"k":"p1","name":"Weather words (chilly, mild, foggy…)","nameCa":"Paraules del temps (chilly, mild, foggy…)","n":6,"slides":[{"theory":"What's the weather like?","img":"🌫️","lines":["noun + **-y**: sun → **sunny** · cloud → **cloudy** · wind → **windy** · fog → **foggy** (sun and fog double the letter)","From cold to hot: **cold** → **chilly** / **cool** → **mild** → **warm** → **hot**. It's **mild** = not hot and not cold.","**Frost** = ice on cars and grass on a very cold morning. In the USA autumn is **fall**."]}]},{"k":"p2","name":"Autumn changes and the harvest","nameCa":"Els canvis de la tardor i la collita","n":6,"slides":[{"theory":"Autumn changes and the harvest","img":"🍂","lines":["At the end of October **the clocks go back** one hour, so **it gets dark early**.","**Leaves change colour** and then **leaves fall** from the trees.","**Harvest** = the time farmers collect the **crops**. **Seasonal** food grows at this time of year: we **pick** mushrooms and apples."]}]},{"k":"p3","name":"Halloween, the Castanyada and feelings","nameCa":"Halloween, la Castanyada i els sentiments","n":7,"slides":[{"theory":"Halloween, the Castanyada and feelings","img":"🌰","lines":["We **roast** chestnuts and sweet potatoes and eat **panellets**. People **carve** pumpkins, and children go **trick or treating**.","Feelings with a preposition: **grateful for** · **proud of** · **scared of** · **excited about**","A warm, comfortable room is **cosy** · calm and happy = **relaxed**"]}]}]},"4eso-ls2-lp2-grammar":{"title":"Grammar · Customs, dates and It is celebrated","parts":[{"k":"p1","name":"Present Simple for customs","nameCa":"Present Simple per als costums","n":5,"slides":[{"theory":"Customs: the Present Simple","img":"🪔","lines":["Customs happen **every year**, so we use the **Present Simple**.",{"table":[["people / families / we / they","he / she / it · my family · Diwali"],["People **light** candles.","Hanukkah **lasts** eight nights."],["We **don't work** on 1 January.","My family **doesn't celebrate** Halloween."],["**Do** you **decorate** the house?","**Does** your town **have** a parade?"]]},{"watch":"**my family**, **the town**, **everybody** = it → verb + -s: Everybody **eats** twelve grapes."}],"ca":["Els costums es repeteixen cada any: Present Simple.","My family, the town, everybody funcionen com it: el verb porta -s."]}]},{"k":"p2","name":"Prepositions of time: on, in, at","nameCa":"Preposicions de temps: on, in, at","n":5,"slides":[{"theory":"When? on, in, at","img":"📅","lines":[{"table":[["on","in","at"],["a date or a day","a month, a season, a year","a festival time, night, a clock time"],["**on** 31 October","**in** November","**at** Christmas"],["**on** New Year's Eve","**in** winter","**at** night"],["**on** Sunday","**in** 2026","**at** midnight"]]},{"watch":"**on** Christmas Day (one day) · **at** Christmas (the holiday time)."}],"ca":["on + data o dia · in + mes, estació o any · at + període de festa, la nit o una hora.","on Christmas Day (el dia), però at Christmas (les festes)."]}]},{"k":"p3","name":"It is celebrated · It takes place · It is held","nameCa":"It is celebrated · It takes place · It is held","n":6,"slides":[{"theory":"It is celebrated · It takes place · It is held","img":"🗓️","lines":["To say **when** and **where** a celebration happens, use these chunks:",{"table":[["Chunk","Example"],["It **is celebrated** in / on…","Diwali **is celebrated** all over the world."],["It **takes place** in / on…","Hanukkah **takes place** in December."],["It **is held** in / on…","The Three Kings parade **is held** on 5 January."]]},"**is celebrated**, **is held** = is / are + past participle: we talk about the celebration, not the people.",{"watch":"~~It is take place~~ → It **takes place**. · ~~It celebrates in India~~ → It **is celebrated** in India."}],"ca":["Per dir quan i on se celebra una festa: It is celebrated… · It takes place… · It is held…","Is celebrated / is held: is + participi. Takes place no porta is."]}]}]},"4eso-ls2-lp2-vocab":{"title":"Vocabulary · Celebrations around the world","parts":[{"k":"p1","name":"Tradition verbs (gather, exchange gifts…)","nameCa":"Verbs de tradicions (gather, exchange gifts…)","n":7,"slides":[{"theory":"Traditions: what people do","img":"🧧","lines":["**get together** / **gather** (meet as a group) · **share a meal** · **exchange gifts** · **make a wish**","**take part in** (participate) · **look forward to** (feel excited about something that is coming)","**pass down** (give to the next generation) · **mark an occasion** (show that a day is special)"]}]},{"k":"p2","name":"Describing a celebration (festive, crowded…)","nameCa":"Descriure una festa (festive, crowded…)","n":6,"slides":[{"theory":"Describing a celebration","img":"🏮","lines":["**religious** (Hanukkah, Diwali) ↔ **secular** (not religious: New Year's Eve) · **traditional**","**local** (one town) ↔ **worldwide** (all over the world) · **family-friendly** (good for all ages)","**colourful** · **crowded** (full of people) · **festive** (happy, like a party) · **meaningful** (important for you)"]}]},{"k":"p3","name":"Celebration words (diyas, lanterns, parade…)","nameCa":"Paraules de festes (diyas, lanterns, parade…)","n":5,"slides":[{"theory":"Words from four celebrations","img":"🪔","lines":["Diwali: **diyas** (small oil lamps) · Hanukkah: a **menorah** (a candle holder)","Lunar New Year: red **lanterns**, a **reunion dinner** (the whole family together) · Christmas: an **Advent calendar**, the **Caga Tió**","Everywhere: a **parade**, **fireworks**, **decorations**, **relatives** (family members), **guests**"]}]}]},"4eso-ls2-lp3-grammar":{"title":"Grammar · Origins, relatives and contrast","parts":[{"k":"p1","name":"Past Simple or used to","nameCa":"Past Simple o used to","n":5,"slides":[{"theory":"Origins: Past Simple or used to?","img":"📜","lines":[{"table":[["","Past Simple","used to + verb"],["Use","**one finished event**, often with a date","a **past habit** that is **not true now**"],["Example","The first Thanksgiving **took** place in 1621. Lincoln **made** it official in 1863.","People **used to** carve turnips. (Now they carve pumpkins.)"],["Negative","They **didn't use** pumpkins.","Children **didn't use to** go trick or treating here."],["Question","When **did** it **start**?","**Did** people **use to** wear masks? — Yes, they **did**."]]},{"watch":"After did / didn't: **use to** (no -d): ~~didn't used to~~ → **didn't use to**."}],"ca":["Past Simple: un fet acabat (sovint amb data). used to: un costum del passat que ara ja no es fa (solia…).","Amb did / didn't escrivim use to, sense -d."]}]},{"k":"p2","name":"Defining relatives: who, which, where, when","nameCa":"Relatius: who, which, where, when","n":4,"slides":[{"theory":"Defining relatives: which person, thing, place or time?","img":"🔗","lines":[{"table":[["For…","use","Example"],["people","**who** (or that)","The Wampanoag were the people **who** lived in the area."],["things","**which** / **that**","Diwali is a festival **which** celebrates light."],["places","**where**","The town square is the place **where** the parade ends."],["times","**when**","31 October is the day **when** we eat panellets."]]},{"watch":"Don't repeat the subject: ~~a festival which it celebrates light~~ → a festival **which celebrates** light."}],"ca":["who per a persones, which / that per a coses, where per a llocs, when per a moments.","No repeteixis it / they després del relatiu."]}]},{"k":"p3","name":"Contrast: whereas, unlike, although","nameCa":"Contrast: whereas, unlike, although","n":4,"slides":[{"theory":"Contrast: whereas, unlike, although","img":"⚖️","lines":["**whereas / while** join two different ideas: Halloween is about costumes, **whereas** the Castanyada is about family.","**unlike** + noun: **Unlike** Hanukkah, Diwali lasts five days.","**although / even though** + sentence: **Although** Halloween started in Europe, it is very popular in the USA.",{"watch":"**However / On the other hand** start a new sentence: Many families love the feast. **However**, some see it as a day of mourning."}],"ca":["whereas / while = mentre que · unlike + nom = a diferència de · although = encara que.","However va al començament d'una frase nova, amb coma."]}]},{"k":"p4","name":"Non-defining relatives (, which …,)","nameCa":"Relatius entre comes (, which …,)","n":3,"slides":[{"theory":"Extra information: non-defining relatives","img":"✍️","lines":["Extra information goes **between commas**: Thanksgiving, **which takes place in November**, became official in 1863.","People: **who** · things: **which**: Abraham Lincoln, **who** was president in 1863, made it official.",{"watch":"Never **that** between commas: Diwali, ~~that~~ **which** is celebrated in autumn, is the festival of lights."}],"ca":["Informació extra entre comes: which (coses) o who (persones). Mai that entre comes."]}]}]},"4eso-ls2-lp3-vocab":{"title":"Vocabulary · Origins, comparing and change","parts":[{"k":"p1","name":"Origins (come from, date back to…)","nameCa":"Orígens (come from, date back to…)","n":7,"slides":[{"theory":"Where does it come from?","img":"📜","lines":["**come from** (have its origin in) · **date back to** (started at that time): Halloween **dates back to** Samhain.","**be known for** (famous for) · **be associated with** (connected in people's minds) · **depend on** · **contribute to**","**once a year** · **the night before** · on **the twenty-fifth** of December · a **harvest festival** · a **feast** (a big meal)"]}]},{"k":"p2","name":"Comparing cultures (both… and, unlike…)","nameCa":"Comparar cultures (both… and, unlike…)","n":5,"slides":[{"theory":"Comparing cultures","img":"⚖️","lines":["**both… and…**: **Both** Diwali **and** Hanukkah use lights. · **similar to** · **different from** · **in the same way**","**whereas** (but, to contrast two ideas) · **unlike** + noun: **Unlike** Hanukkah, Diwali lasts five days.","Places: **travel home for the holidays** · the **town square** · the **community centre** · **crowded** streets (full of people)"]}]},{"k":"p3","name":"Traditions change (evolve, die out…)","nameCa":"Les tradicions canvien (evolve, die out…)","n":6,"slides":[{"theory":"Traditions change","img":"🔁","lines":["**evolve** · **adapt** · **reinvent** · **keep a tradition alive** ↔ **die out** (disappear)","**commercialised** (all about buying and selling) · **consumerism** · **take something for granted** (not value it)","a **stereotype** (a fixed, simple idea about a group) · **inclusive** (everyone is welcome) · **pilgrims** (the English settlers in 1621)"]}]}]}};
